#pragma once

namespace sdp::win {

struct PacketBuffer;

/// Receives packets generated by the engine (fake requests and native
/// fragments). The caller stays responsible for reinjecting or dropping the
/// original packet based on the processing result.
class PacketSink {
public:
    virtual ~PacketSink() = default;

    /// Returns false when the generated packet could not be sent.
    [[nodiscard]] virtual bool send(const PacketBuffer& packet) = 0;
};

} // namespace sdp::win
